from collections import deque

def comps(grid, ignore=(0,1,4), connectivity=4):
    R,C=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(R):
      for c in range(C):
       if grid[r][c] not in ignore and (r,c) not in seen:
        col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); pts=[]
        while q:
         x,y=q.pop();pts.append((x,y))
         for dx,dy in ([(1,0),(-1,0),(0,1),(0,-1)] if connectivity==4 else [(a,b) for a in [-1,0,1] for b in [-1,0,1] if a or b]):
          xx,yy=x+dx,y+dy
          if 0<=xx<R and 0<=yy<C and grid[xx][yy]==col and (xx,yy) not in seen:
           seen.add((xx,yy));q.append((xx,yy))
        out.append((col,pts))
    return out

