def code_box(g):
    R,C=len(g),len(g[0]); bg=Counter(sum(g,[])).most_common(1)[0][0]
    fullrows=[r for r,row in enumerate(g) if len(set(row))==1 and row[0]!=bg]
    for t in fullrows:
      border=g[t][0]
      for b in fullrows:
       if b<=t:continue
       cs=[c for c in range(C) if all(g[r][c]==border for r in range(t,b+1))]
       if len(cs)>=2:
        # contiguous rectangle border
        l,rr=min(cs),max(cs)
        if all(g[t][c]==border and g[b][c]==border for c in range(l,rr+1)):
         return t,b,l,rr,border
    raise ValueError('no box')

def transform(g):
    t,b,l,rr,border=code_box(g)
    code=[row[l:rr+1] for row in g[t:b+1]]
    H,W=len(code),len(code[0])
    fg=Counter(v for row in code for v in row if v!=border).most_common(1)[0][0]
    outside=[v for r,row in enumerate(g) for c,v in enumerate(row) if not(t<=r<=b and l<=c<=rr)]
    bg=Counter(outside).most_common(1)[0][0]
    objs=[]
    for col,pts in comps(g,ignore=(bg,border)):
      if all(not(t<=r<=b and l<=c<=rr) for r,c in pts):objs.append((col,norm(pts)))
    shapes=[]
    for i,(col,p) in enumerate(objs):
      for k,o in enumerate(rotates(p)):shapes.append((o,col,i,k))
    out=[[fg]*W for _ in range(H)]
    bincode=[[1 if v==fg else 0 for v in row] for row in code]
    for _,pts0 in comps(bincode,ignore=(0,)):
      base_r=min(r for r,c in pts0);base_c=min(c for r,c in pts0);pts=norm(pts0)
      exact=[(k,i,col) for p,col,i,k in shapes if p==pts]
      if exact:
       k,i,col=min(exact)
       for r,c in pts:out[base_r+r][base_c+c]=col
       continue
      bybit={}
      for p,col,i,k in shapes:
       h=max(r for r,c in p)+1;w=max(c for r,c in p)+1
       Hp=max(r for r,c in pts)+1;Wp=max(r for r,c in pts)+1
       for dr in range(Hp-h+1):
        for dc in range(Wp-w+1):
         placed=frozenset((r+dr,c+dc) for r,c in p)
         if placed<=pts:bybit.setdefault(placed,(col,i,k))
      plist=list(bybit)
      @lru_cache(None)
      def solve(rem):
       if not rem:return ()
       first=min(rem);opts=[]
       for p in plist:
        if first in p and p<=rem:
         col,i,k=bybit[p];sub=solve(rem-p)
         if sub is not None:opts.append(((k,i,p,col),)+sub)
       return min(opts,key=lambda sol:(sum(x[0] for x in sol),tuple(x[1] for x in sol))) if opts else None
      sol=solve(pts)
      if sol is None:raise ValueError(f'cannot tile {pts}')
      for k,i,p,col in sol:
       for r,c in p:out[base_r+r][base_c+c]=col
    return out
